"""
Google Gemini-Powered Clinical Report & Disease Profile Generation Service
Combines 3D DenseNet-121 inference, hippocampal volumetrics, and 3D Grad-CAM
features into human-level diagnostic disease profiles and AD early warning assessments.
"""

import json
import os
from pathlib import Path
from typing import Dict, Any, List, Optional
from loguru import logger
from config.settings import settings

try:
    from google import genai
    HAS_GENAI = True
except ImportError:
    HAS_GENAI = False

STANDARD_DISCLAIMER = (
    "This report was generated by a research decision-support tool. It is not a medical diagnosis "
    "and does not replace evaluation by a qualified healthcare professional. Please consult a neurologist."
)

def get_gemini_api_key() -> str:
    """Finds and validates the Gemini API key from environment or .env files."""
    candidates = []
    # 1. Direct environment variable
    if os.environ.get("GEMINI_API_KEY"):
        candidates.append(os.environ["GEMINI_API_KEY"])

    # 2. Settings
    if getattr(settings, "GEMINI_API_KEY", None):
        candidates.append(settings.GEMINI_API_KEY)

    # 3. Read directly from .env files
    env_paths = [
        Path("/Users/sriram/Downloads/AD-WEB/backend/.env"),
        Path("/Users/sriram/Downloads/AD-WEB/.env"),
        Path(__file__).resolve().parent.parent.parent / "backend" / ".env",
        Path(__file__).resolve().parent.parent.parent / ".env",
        Path(".env"),
        Path("backend/.env"),
    ]
    for p in env_paths:
        if p.exists():
            try:
                for line in p.read_text().splitlines():
                    line = line.strip()
                    if line.startswith("GEMINI_API_KEY="):
                        val = line.split("=", 1)[1].strip().strip('"').strip("'")
                        if val:
                            candidates.append(val)
            except Exception:
                pass

    for key in candidates:
        cleaned = key.strip()
        if cleaned and "YOUR_GEMINI" not in cleaned and len(cleaned) > 10:
            return cleaned
    return ""


def _call_gemini(prompt: str, json_mode: bool = True, temperature: float = 0.65) -> Optional[tuple[str, str]]:
    """Calls Gemini across ordered fallback candidates; returns (text, model_name) or None."""
    api_key = get_gemini_api_key()
    if not (HAS_GENAI and api_key):
        return None

    models_to_try = [
        settings.GEMINI_MODEL,
        "gemini-2.0-flash",
        "gemini-1.5-flash",
        "gemini-2.5-flash",
        "gemini-flash-latest",
    ]
    candidate_models = list(dict.fromkeys(models_to_try))
    config: Dict[str, Any] = {"temperature": temperature}
    if json_mode:
        config["response_mime_type"] = "application/json"

    client = genai.Client(api_key=api_key)
    for model_name in candidate_models:
        try:
            resp = client.models.generate_content(
                model=model_name,
                contents=prompt,
                config=config,
            )
            if resp.text:
                return resp.text, model_name
        except Exception as e:
            logger.warning(f"Gemini API generation with {model_name} failed ({e}); trying next candidate.")
    return None


def _normalize_profile_response(data: Dict[str, Any], stage: str) -> Dict[str, Any]:
    """Ensures Gemini output has all 5 clean report sections and fixed safety disclaimer."""
    cp = data.setdefault("clinical_profile", {})
    cp.setdefault("disease", stage)
    cp.setdefault(
        "where_seen",
        "Across the 3D scan, the model's strongest overall attention centers on the medial temporal region and hippocampus (the brain area responsible for forming memories). Highlighted areas shift as you navigate slices and views, and show where the model focused—not confirmed tissue loss.",
    )
    if "not confirmed tissue loss" not in cp["where_seen"].lower():
        cp["where_seen"] = cp["where_seen"].rstrip(".") + ". This shows where the model focused, not confirmed tissue loss."

    tips = cp.get("prevention_tips")
    if not isinstance(tips, list) or not tips:
        cp["prevention_tips"] = [
            "Stay active: Engage in regular walking or aerobic exercise",
            "Brain-healthy diet: Eat a balanced, Mediterranean-style diet",
            "Heart & metabolic care: Control blood pressure, blood sugar, and cholesterol",
            "Quality sleep: Sleep well and avoid smoking or heavy alcohol use",
            "Mental & social life: Stay mentally engaged and socially connected",
            "Health checkups: Treat hearing loss and depression early",
            "Head safety: Protect your head from falls and injury",
        ]
    else:
        cp["prevention_tips"] = [str(item).strip().lstrip("-• ").strip() for item in tips if str(item).strip()]

    # Ensure structured causes_breakdown exists alongside why_it_happens
    cb = cp.get("causes_breakdown")
    if not isinstance(cb, dict):
        cb = {}
    s_u = (stage or "").upper()
    is_cn_s = "CN" in s_u or "NORMAL" in s_u
    default_brain = (
        "Healthy brain aging with preserved memory pathways and no significant amyloid or tau protein buildup."
        if is_cn_s
        else "Early accumulation of proteins such as amyloid and tau, or reduced blood flow affecting memory pathways."
    )
    default_treatable = (
        "Blood pressure, blood sugar, cholesterol, sleep quality, and vitamin or thyroid health still influence long-term cognitive reserve."
    )
    cb["brain_changes"] = str(cb.get("brain_changes") or "").strip() or default_brain
    cb["treatable_risks"] = str(cb.get("treatable_risks") or "").strip() or default_treatable
    cp["causes_breakdown"] = cb

    if not cp.get("why_it_happens"):
        cp["why_it_happens"] = f"{cb['brain_changes']} {cb['treatable_risks']}"

    # Always enforce exact clinical disclaimer wording
    cp["disclaimer"] = STANDARD_DISCLAIMER
    return data


def generate_clinical_ai_profile(
    stage: str,
    confidence: float,
    probabilities: Dict[str, float],
    hippocampus_volume_mm3: float,
    patient_age: Optional[str] = "70",
    gender: Optional[str] = "Unspecified",
    patient_id: Optional[str] = "Anonymous",
    peak_slices: Optional[Dict[str, int]] = None,
    variation_seed: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Uses Google Gemini to dynamically generate:
    1. "ad_signal": Alzheimer's Disease early-warning assessment (alerting even on >=1% AD).
    2. "clinical_profile": Clean 5-section plain-language report:
       (1) Disease, (2) Where it is seen in the 3D image, (3) Why it happens,
       (4) How to prevent or lower the risk, (5) Disclaimer.

    Falls back gracefully if GEMINI_API_KEY is missing or an API error occurs.
    """
    api_key = get_gemini_api_key()
    is_valid_key = bool(api_key)
    logger.info(f"generate_clinical_ai_profile: is_valid_key={is_valid_key}, key_len={len(api_key)}, HAS_GENAI={HAS_GENAI}")

    cn_prob = probabilities.get("cn", 0.0)
    mci_prob = probabilities.get("mci", 0.0)
    ad_prob = probabilities.get("ad", 0.0)

    cn_pct = round(cn_prob * 100 if cn_prob <= 1.0 else cn_prob, 1)
    mci_pct = round(mci_prob * 100 if mci_prob <= 1.0 else mci_prob, 1)
    ad_pct = round(ad_prob * 100 if ad_prob <= 1.0 else ad_prob, 1)

    peak_info = f"- 3D Grad-CAM Peak Slice Coordinates: {peak_slices}" if peak_slices else ""

    s_upper = (stage or "").upper()
    is_primary_ad = ("AD" in s_upper or "ALZHEIMER" in s_upper) and "CN" not in s_upper and "MCI" not in s_upper

    if is_primary_ad:
        ad_signal_instruction = f"""1. "ad_signal": The primary predicted stage IS Alzheimer's Disease (AD) with {ad_pct}% probability:
   - "title": "Primary AD Signal ({ad_pct}%)"
   - "badge": "{ad_pct}% AD Risk"
   - "narrative": 2 clear sentences stating that Alzheimer's Disease (AD) is the primary classification at {ad_pct}% probability, reflecting prominent Alzheimer's-related structural patterns in the scan, and recommending prompt evaluation by a neurologist. Do NOT call it "subtle" and do NOT say "even though the primary label...".
   - "alert_level": "{"severe" if ad_pct >= 50 else "high"}" """
    elif ad_pct >= 20:
        ad_signal_instruction = f"""1. "ad_signal": Primary stage is {stage}, while secondary Alzheimer's Disease (AD) probability is {ad_pct}%:
   - "title": "Notable AD Biomarker Signal ({ad_pct}%)"
   - "badge": "{ad_pct}% AD Risk"
   - "narrative": 2 clear sentences explaining that although the primary classification is {stage}, the model detected a substantial {ad_pct}% Alzheimer's-like structural signal, warranting timely clinical follow-up.
   - "alert_level": "high" """
    elif ad_pct >= 1:
        ad_signal_instruction = f"""1. "ad_signal": Primary stage is {stage}, while secondary Alzheimer's Disease (AD) probability is {ad_pct}%:
   - "title": "Early AD Biomarker Traces ({ad_pct}%)"
   - "badge": "{ad_pct}% AD Risk"
   - "narrative": 2 clear sentences explaining that although the primary classification is {stage}, subtle Alzheimer's-like patterns were detected with a {ad_pct}% probability, providing a proactive window for timely medical follow-up and monitoring.
   - "alert_level": "mild" """
    else:
        ad_signal_instruction = f"""1. "ad_signal": Primary stage is {stage} and Alzheimer's Disease (AD) probability is {ad_pct}% (<1%):
   - "title": "Negligible AD Signature (<1%)"
   - "badge": "{ad_pct}% AD Risk"
   - "narrative": 1-2 short sentences stating that virtually no structural patterns resembling Alzheimer's Disease were detected ({ad_pct}%).
   - "alert_level": "none" """

    if HAS_GENAI and is_valid_key:
        variation_note = (
            f"\n- Regeneration Seed: {variation_seed} (IMPORTANT: Rephrase all narratives and prevention tips with fresh, distinct wording and varied practical examples while keeping medical facts accurate.)"
            if variation_seed
            else ""
        )
        prompt = f"""
You are a medical communicator and neuro-imaging assistant explaining a 3D Brain MRI AI result in clear, patient-friendly language without unnecessary technical jargon.

SCAN METRICS:
- Patient ID: {patient_id} | Age: {patient_age} years | Gender: {gender}
- Predicted Stage: {stage} ({confidence:.1f}% confidence)
- Class Probabilities: CN={cn_pct}%, MCI={mci_pct}%, AD={ad_pct}%
- Estimated Hippocampus Volume: {hippocampus_volume_mm3:.1f} mm³
{peak_info}{variation_note}

INSTRUCTIONS:
Return strict JSON with two top-level keys ("ad_signal" and "clinical_profile"). Keep every field concise, accurate, and free of clutter:

{ad_signal_instruction}

2. "clinical_profile": Generate a clean 5-part report matching this exact structure (NO extra metrics, NO atrophy ratings, NO technical filler):
   - "badge": "Healthy / Low Risk" (for CN), "Prodromal / Moderate Risk" (for MCI), or "High Risk" (for AD)
   - "disease": Clean disease/stage name, e.g. "{stage}"
   - "where_seen": 2 short plain sentences describing the OVERALL 3D scan focus (not tied to a single fixed slice or color theme): mention the primary brain region across the 3D volume (e.g., medial temporal region and hippocampus—briefly noting in parentheses "(the brain area responsible for forming memories)"—or preserved baseline regions for CN) and note that highlighted hotspots shift across slices and views. MUST end with: "This shows where the model focused, not confirmed tissue loss."
   - "why_it_happens": 1-2 short plain-language sentences summarizing why {stage} appears.
   - "causes_breakdown": Object with two concise plain-language fields (1-2 sentences each, varied wording):
     * "brain_changes": Primary biological/brain processes (e.g., amyloid/tau protein buildup or reduced brain blood flow; for CN, note preserved memory pathways and healthy aging).
     * "treatable_risks": Modifiable/treatable medical & lifestyle factors a doctor can check and manage (blood pressure, diabetes, cholesterol, sleep issues, vitamin/thyroid imbalances, or hearing/mood).
   - "prevention_tips": Array of 6-7 scannable bullet strings formatted strictly as "Short Action Label: fresh practical advice" (no leading bullets/numbers). Cover these 7 evidence-based pillars using fresh wording each time: (1) regular aerobic/physical movement, (2) Mediterranean/brain-healthy nutrition, (3) blood pressure/blood sugar/cholesterol management, (4) quality sleep & avoiding smoking/heavy alcohol, (5) cognitive & social engagement, (6) treating hearing loss or mood/depression early, (7) fall & head-injury prevention.
   - "disclaimer": "{STANDARD_DISCLAIMER}"

OUTPUT FORMAT (pure JSON only):
{{
  "ad_signal": {{
    "title": "string",
    "badge": "string",
    "narrative": "string",
    "alert_level": "string"
  }},
  "clinical_profile": {{
    "badge": "string",
    "disease": "string",
    "where_seen": "string",
    "why_it_happens": "string",
    "causes_breakdown": {{
      "brain_changes": "string",
      "treatable_risks": "string"
    }},
    "prevention_tips": ["string"],
    "disclaimer": "string"
  }}
}}
"""
        result = _call_gemini(
            prompt,
            json_mode=True,
            temperature=0.9 if variation_seed else 0.65,
        )
        if result:
            raw_text, model_name = result
            try:
                data = json.loads(raw_text)
                data = _normalize_profile_response(data, stage)
                data["source"] = "gemini"
                data["model"] = model_name
                logger.info(f"Successfully generated dynamic clinical report profile using Google Gemini ({model_name})!")
                return data
            except Exception as e:
                logger.warning(f"Failed to parse Gemini JSON ({e}); falling back.")

    # Algorithmic fallback if Gemini key is not set or API error occurs
    return _generate_dynamic_fallback(stage, confidence, cn_pct, mci_pct, ad_pct, hippocampus_volume_mm3)


def _generate_dynamic_fallback(
    stage: str,
    confidence: float,
    cn_pct: float,
    mci_pct: float,
    ad_pct: float,
    hippo_vol: float,
) -> Dict[str, Any]:
    """Generates clean 5-section structured fallback profile when offline or awaiting API key."""
    s = (stage or "").upper()
    is_cn = "CN" in s or "NORMAL" in s
    is_mci = "MCI" in s or "MILD" in s

    # 1. AD Signal
    if not is_cn and not is_mci:
        ad_title = f"Primary AD Signal ({ad_pct}%)"
        ad_alert = "severe" if ad_pct >= 50 else "high"
        ad_text = (
            f"Alzheimer's Disease (AD) is the primary classification at {ad_pct}% probability, "
            "reflecting prominent Alzheimer's-related structural patterns in the scan. Prompt neurological evaluation and follow-up are recommended."
        )
    elif ad_pct >= 20:
        ad_title = f"Notable AD Biomarker Signal ({ad_pct}%)"
        ad_alert = "high"
        ad_text = (
            f"Although the primary label is {stage}, the model detected {ad_pct}% structural patterns "
            "resembling Alzheimer's pathology. Timely clinical follow-up is recommended."
        )
    elif ad_pct >= 1:
        ad_title = f"Early AD Biomarker Traces ({ad_pct}%)"
        ad_alert = "mild"
        ad_text = (
            f"Although the primary classification is {stage}, subtle Alzheimer's-like patterns were detected with a {ad_pct}% probability. "
            "Early detection provides a proactive window for timely medical follow-up and monitoring."
        )
    else:
        ad_title = "Negligible AD Signature (<1%)"
        ad_alert = "none"
        ad_text = (
            "Virtually no structural patterns resembling Alzheimer's Disease were detected (<1%)."
        )

    # 2. Clean 5-Section Clinical Profile
    if is_cn:
        badge = "Healthy / Low Risk"
        disease = "Cognitively Normal (CN)"
        where_seen = (
            "Across the 3D scan, attention remains balanced across preserved medial temporal regions and the hippocampus "
            "(the brain area responsible for forming memories), with highlights shifting naturally across slices and views. "
            "This shows where the model focused, not confirmed tissue loss."
        )
        why_it_happens = (
            "A Cognitively Normal pattern reflects healthy brain aging without significant Alzheimer's-related protein build-up "
            "or vascular damage."
        )
        causes_breakdown = {
            "brain_changes": "Memory-related brain networks appear well preserved without significant protein plaque buildup or vascular tissue injury.",
            "treatable_risks": "Older age, high blood pressure, diabetes, cholesterol, and sleep habits still influence long-term brain health and are worth monitoring.",
        }
    elif is_mci:
        badge = "Prodromal / Moderate Risk"
        disease = "Mild Cognitive Impairment (MCI)"
        where_seen = (
            "Across the 3D scan, the model's strongest overall attention centers on the medial temporal region and areas around the hippocampus "
            "(the brain area responsible for forming memories), with hotspot locations shifting as you move through slices. "
            "This shows where the model focused, not confirmed tissue loss."
        )
        why_it_happens = (
            "MCI can stem from early Alzheimer's-related changes, reduced cerebral blood flow, or other medical factors."
        )
        causes_breakdown = {
            "brain_changes": "Early buildup of amyloid or tau proteins and reduced blood circulation can disrupt signaling in memory pathways.",
            "treatable_risks": "High blood pressure, diabetes, cholesterol, sleep disorders, and vitamin (B12) or thyroid imbalances are important manageable contributors.",
        }
    else:
        badge = "High Risk"
        disease = "Alzheimer's Disease (AD)"
        where_seen = (
            "Across the 3D scan, the model's strongest overall attention centers on the medial temporal lobe, hippocampus "
            "(the brain area responsible for forming memories), and surrounding fluid spaces, shifting as you navigate slices and views. "
            "This shows where the model focused, not confirmed tissue loss."
        )
        why_it_happens = (
            "Alzheimer's Disease is driven by amyloid plaque and tau protein buildup that impairs nerve cell communication."
        )
        causes_breakdown = {
            "brain_changes": "Abnormal amyloid plaques and tau tangles progressively injure nerve cells, often alongside reduced brain blood flow.",
            "treatable_risks": "Age and family history raise risk, while blood pressure, diabetes, cholesterol, sleep, and mood/hearing care remain important to manage.",
        }

    prevention_tips: List[str] = [
        "Stay active: Engage in regular walking or aerobic exercise",
        "Brain-healthy diet: Eat a balanced, Mediterranean-style diet",
        "Heart & metabolic care: Control blood pressure, blood sugar, and cholesterol",
        "Quality sleep: Sleep well and avoid smoking or heavy alcohol use",
        "Mental & social life: Stay mentally engaged and socially connected",
        "Health checkups: Treat hearing loss and depression early",
        "Head safety: Protect your head from falls and injury",
    ]

    return {
        "ad_signal": {
            "title": ad_title,
            "badge": f"{ad_pct}% AD Risk",
            "narrative": ad_text,
            "alert_level": ad_alert,
        },
        "clinical_profile": {
            "badge": badge,
            "disease": disease,
            "where_seen": where_seen,
            "why_it_happens": why_it_happens,
            "causes_breakdown": causes_breakdown,
            "prevention_tips": prevention_tips,
            "disclaimer": STANDARD_DISCLAIMER,
        },
        "source": "fallback",
        "note": "Configure GEMINI_API_KEY in backend/.env for live Google Gemini LLM generation.",
    }


def chat_about_scan(
    message: str,
    history: Optional[List[Dict[str, str]]] = None,
    scan_context: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Answers user questions across all AD-WEB pages using Google Gemini:
    - When an active MRI scan is present, tailors answers to its stage, probabilities, and live slice/viewer state.
    - When no scan is loaded (e.g. Home, Upload, History, About), acts as an AD-WEB & Alzheimer's guide.
    """
    ctx = scan_context or {}
    stage = (ctx.get("stage") or "").strip()
    has_scan = bool(stage and stage.lower() not in ("unknown", "none"))
    page = ctx.get("page", "/")

    recent_turns = (history or [])[-8:]
    history_text = "\n".join(
        f"{'User' if turn.get('role') == 'user' else 'Assistant'}: {turn.get('text', '')}"
        for turn in recent_turns
        if turn.get("text")
    )

    if has_scan:
        confidence = ctx.get("confidence", 0)
        probs = ctx.get("probabilities") or {}
        cn_pct = round(float(probs.get("cn", 0)) * (100 if float(probs.get("cn", 0)) <= 1 else 1), 1)
        mci_pct = round(float(probs.get("mci", 0)) * (100 if float(probs.get("mci", 0)) <= 1 else 1), 1)
        ad_pct = round(float(probs.get("ad", 0)) * (100 if float(probs.get("ad", 0)) <= 1 else 1), 1)

        viewer = ctx.get("viewer") or {}
        plane = viewer.get("plane", "axial")
        slice_num = viewer.get("slice_number", 48)
        channel = viewer.get("channel", "predicted")
        colormap = viewer.get("colormap", "turbo")
        slice_note = viewer.get("slice_note", "")

        context_block = f"""ACTIVE SCAN CONTEXT (User is currently on page: {page}):
- Primary AI Classification: {stage} ({confidence}% confidence)
- Class Probabilities: CN={cn_pct}%, MCI={mci_pct}%, AD={ad_pct}%
- Current 3D Viewer State: Plane={plane}, Slice=#{slice_num}, Channel={channel}, Colormap={colormap}
- Active Slice Observation: {slice_note}"""
        fallback_reply = (
            f"Your active scan shows {stage} ({confidence}% confidence), with probabilities of "
            f"CN {cn_pct}%, MCI {mci_pct}%, and AD {ad_pct}%. On the heatmap, brightest colors mark where the AI focused most strongly "
            "(not confirmed tissue loss). Please discuss these results and any follow-up steps with a neurologist."
        )
    else:
        context_block = f"""APP CONTEXT (User is currently on page: {page}; no MRI scan loaded yet):
- Platform: AD-WEB — an AI research decision-support tool using a 3D DenseNet-121 model and 3D Grad-CAM heatmaps on structural brain MRI (.nii / .nii.gz) scans.
- Stages classified: Cognitively Normal (CN), Mild Cognitive Impairment (MCI), and Alzheimer's Disease (AD).
- Features: Upload MRI scans, inspect 3D Axial/Coronal/Sagittal Grad-CAM heatmaps, view dynamic clinical reports, and check Scan History."""
        fallback_reply = (
            "AD-WEB analyzes 3D brain MRI (.nii / .nii.gz) scans using a 3D DenseNet-121 model and visualizes focal areas with 3D Grad-CAM heatmaps. "
            "You can upload a scan on the Upload MRI page to view your personalized Dashboard report. For personal medical advice, always consult a neurologist."
        )

    prompt = f"""
You are a helpful, calm medical & platform assistant inside AD-WEB (an AI 3D Brain MRI Alzheimer's research decision-support web app).

{context_block}

GUIDELINES:
- Answer the user's question directly in clear, empathetic, plain language (3-5 short sentences or concise bullet points).
- If scan data is present above, reference their actual numbers or viewer state when relevant.
- If no scan is loaded, answer questions about Alzheimer's, MCI, brain MRI scans, Grad-CAM heatmaps, prevention, or how to use AD-WEB clearly.
- Clarify when asked about heatmaps that Grad-CAM highlights where the AI focused, NOT confirmed tissue loss.
- Do NOT diagnose definitively or prescribe medications/dosages; recommend consulting a qualified neurologist for clinical decisions.

RECENT CONVERSATION:
{history_text or "(New conversation)"}

USER QUESTION:
{message}

Respond directly in plain text (no JSON, no markdown code blocks).
"""
    result = _call_gemini(prompt, json_mode=False, temperature=0.55)
    if result:
        reply_text, model_name = result
        return {
            "reply": reply_text.strip(),
            "source": "gemini",
            "model": model_name,
        }

    return {
        "reply": fallback_reply,
        "source": "fallback",
        "model": None,
    }
